{{ (function(){
  var css = "*{box-sizing:border-box}body{margin:0;padding:18px 22px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#1F2937;background:#fff;line-height:1.55;font-size:14px}h1{font-size:19px;margin:0 0 4px;color:#B4232A}.aika{color:#6B7280;font-size:12px;margin:0 0 16px}h2{font-size:15px;margin:20px 0 8px;color:#111827;border-bottom:1px solid #E5E7EB;padding-bottom:4px}p{margin:8px 0}ol,ul{margin:8px 0;padding-left:22px}li{margin:6px 0}a{color:#B4232A;font-weight:600;text-decoration:none;border-bottom:1px solid rgba(180,35,42,.35)}a:hover{background:#FEF2F2}strong{font-weight:650}.tyhja{color:#6B7280;font-style:italic}";
  var kortti = "https://kilpipaino.appsmith.com/app/tyonhallinta/tyokortti-6a6f2badadc4847fb5c530e0?branch=master&id=";
  var d = (haeAamuraportti.data && haeAamuraportti.data[0]) || {};
  var ots = d.otsikko || 'Aamuraportti';
  var txt = d.teksti || '';
  var map = d.tp_linkit || {};
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function muotoile(s){ s = esc(s); s = s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
    s = s.replace(/TP-\d{4}-\d{4}/g, function(tp){ var id = map[tp];
      return id ? ('<a href="' + kortti + id + '" target="_top" rel="noopener" title="Avaa työkortti ">' + tp + '</a>') : tp; }); return s; }
  var html = '';
  if (!txt) { html = '<p class="tyhja">Aamuraporttia ei ole vielä luotu. Raportti kirjoitetaan arkiaamuisin klo 7.00.</p>'; }
  else {
    var rivit = txt.split(/\r?\n/), lista = null, out = [];
    for (var i=0;i<rivit.length;i++){ var r = rivit[i].trim();
      if (!r) { if(lista){out.push('</'+lista+'>');lista=null;} continue; }
      var h = r.match(/^#{1,4}\s+(.*)$/);
      if (h) { if(lista){out.push('</'+lista+'>');lista=null;} out.push('<h2>'+muotoile(h[1])+'</h2>'); continue; }
      var num = r.match(/^\d+[.)]\s+(.*)$/);
      if (num) { if(lista!=='ol'){ if(lista)out.push('</'+lista+'>'); out.push('<ol>'); lista='ol'; } out.push('<li>'+muotoile(num[1])+'</li>'); continue; }
      var bul = r.match(/^[-*\u2022]\s+(.*)$/);
      if (bul) { if(lista!=='ul'){ if(lista)out.push('</'+lista+'>'); out.push('<ul>'); lista='ul'; } out.push('<li>'+muotoile(bul[1])+'</li>'); continue; }
      if(lista){out.push('</'+lista+'>');lista=null;}
      out.push('<p>'+muotoile(r)+'</p>');
    }
    if(lista) out.push('</'+lista+'>');
    html = out.join('');
  }
  var aika = d.luotu ? ('<p class="aika">Koottu ' + esc(d.luotu) + ' · työnumeroa klikkaamalla pääsee työkortille</p>') : '';
  return '<!doctype html><html><head><meta charset="utf-8"><base target="_top"><style>' + css + '</style></head><body><h1>' + esc(ots) + '</h1>' + aika + html + '</body></html>';
})() }}
